// Приводит update от MAX к единому виду: {type, user_id, first_name, text, callback_id, payload}
const u = $input.first().json.body ?? $input.first().json;
const t = u.update_type;

if (t === 'message_callback') {
  return [{ json: {
    type: 'callback',
    user_id: u.callback.user.user_id,
    first_name: u.callback.user.first_name,
    callback_id: u.callback.callback_id,
    payload: u.callback.payload,
  } }];
}
if (t === 'bot_started') {
  return [{ json: { type: 'start', user_id: u.user.user_id, first_name: u.user.first_name } }];
}
if (t === 'message_created') {
  const m = u.message;
  if (!m.sender || m.sender.is_bot) return [];
  return [{ json: {
    type: 'text',
    user_id: m.sender.user_id,
    first_name: m.sender.first_name,
    text: m.body?.text ?? '',
  } }];
}
return []; // остальные типы событий игнорируем

// Движок сценария Robochat → n8n. Сценарий подставляется генератором build_n8n.py.
const SCENARIO = {"start": "s35", "keywords": [{"word": "Здравствуйте", "to": "s35"}, {"word": "Добрый день", "to": "s35"}, {"word": "В начало", "to": "s35"}, {"word": "интернет", "to": "s9"}, {"word": "Привет", "to": "s35"}, {"word": "/start", "to": "s35"}, {"word": "Начало", "to": "s35"}, {"word": "start", "to": "s35"}, {"word": "старт", "to": "s35"}], "steps": {"s0": {"title": "Заказ QR", "blocks": [{"t": "msg", "text": "Заказ QR", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s1": {"title": "Печать ценников чере", "blocks": [{"t": "msg", "text": "Печать ценников через пред.просмотр", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s2": {"title": "Приёмка товара ордер", "blocks": [{"t": "msg", "text": "https://disk.yandex.ru/client/disk/%D0%90%D0%BA%D1%82%D1%8B%20%D1%80%D0%B0%D1%81%D1%85%D0%BE%D0%B6%D0%B4%D0%B5%D0%BD%D0%B8%D0%B9", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s3": {"title": "Проблемный чек", "blocks": [{"t": "msg", "text": "Проблемный чек", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s4": {"title": "ИБП (Источник беспер", "blocks": [{"t": "msg", "text": "Если ИБП издаёт звуковые сигналы, необходимо выключить его на 10 минут, вытащить из него все подключенные приборы и затем заново подключить. Если звуковые сигналы возникли вновь, необходима замена аккумуляторной батареи.\nВ этом случае сделайте заявку на sd@modi.ru", "buttons": [{"text": "Назад", "to": "s6"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s5": {"title": "Сертификаты", "blocks": [{"t": "delay", "seconds": 3}, {"t": "msg", "text": "htt