т появился?", "buttons": [{"text": "Да, интернет появился", "to": "s12"}, {"text": "Нет, интернет не появился", "to": "s32"}]}], "next": null}, "s14": {"title": "Действие", "blocks": [{"t": "notify"}], "next": null}, "s15": {"title": "Сверка итогов", "blocks": [{"t": "msg", "text": "Сверка итогов", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s16": {"title": "Индикация есть", "blocks": [{"t": "delay", "seconds": 5}, {"t": "msg", "text": "Перезагружали роутер Mikrotik?", "buttons": [{"text": "Да, не помогло", "to": "s32"}, {"text": "Нет, сейчас перезагрузим", "to": "s30"}, {"text": "А как это сделать?", "to": "s30"}, {"text": "В начало", "to": "s26"}]}], "next": null}, "s18": {"title": "Заявка в ServiceDesk", "blocks": [{"t": "msg", "text": "Перейдите по ссылке и заполните форму заявки www.modi.ru/sd", "buttons": [{"text": "В начало", "to": "s26"}]}], "next": null}, "s19": {"title": "Принтер", "blocks": [{"t": "msg", "text": "Если вам не подходят данные пункты, сделайте заявку в Service Desk.", "buttons": [{"text": "Замятие бумаги", "to": "s29"}, {"text": "Заказ картриджа", "to": "s22"}, {"text": "Назад", "to": "s6"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s20": {"title": "Сообщение #1", "blocks": [{"t": "msg", "text": "Перезагрузили?", "buttons": [{"text": "Да, интернет появился", "to": "s12"}, {"text": "Да, интернет не появился", "to": "s32"}]}], "next": null}, "s21": {"title": "Видеонаблюдение", "blocks": [{"t": "msg", "text": "По вопросам неисправности видеонаблюдения сделайте заявку на sd@modi.ru\nПо вопросам переноса камер, добавления, изменения угла обзора и т.п., необходимо обратиться в Службу Безопасности к Сергею Завьялову.", "buttons": [{"text": "Назад", "to": "s6"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s22": {"title": "Заказ картриджа", "blocks": [{"t": "msg", "text": "Для заказа картриджа необходимо написать письмо на sd@modi.ru с просьбой выслать ссылку на картридж в Комусе. В письме необходимо указать модель вашего МФУ. В копию письма поставить Маргариту Артюшкову m.artyshkova@modi.ru", "buttons": [{"text": "Назад", "to": "s19"}, {"text": "В начало", "to": "s26"}]}], "next": null}, "s23": {"title": "Отмена операции по э", "blocks": [{"t": "msg", "text": "Отмена операции по эквайрингу", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s25": {"title": "Проблемы с 1С", "blocks": [{"t": "msg", "text": "Выберите пункт", "buttons": [{"text": "Сверка итогов", "to": "s15"}, {"text": "Проблемный чек", "to": "s3"}, {"text": "Заказ QR", "to": "s0"}, {"text": "Работа с новым ТСД АТОЛ", "to": "s37"}, {"text": "Приёмка товара ордерная", "to": "s2"}, {"text": "Сертификаты", "to": "s5"}, {"text": "Печать ценников через пред.просмотр", "to": "s1"}, {"text": "Возврат при оплате по QR-коду", "to": "s40"}, {"text": "Отмена по эквайрингу (Ошибка  D3h)", "to": "s23"}, {"text": "В начало", "to": "s26"}]}], "next": null}, "s26": {"title": "Назад", "blocks": [{"t": "msg", "text": "{{first name}}, выберите необходимый пункт.\n\n   Но перед тем как выбрать пункт, необходимо помнить, что большинство неисправностей лечится перезагрузкой оборудования.\n\n   Выберите необходимый пункт по вашей неисправности. Если вашей неисправности нет в списке, сделайте заявку с описанием проблемы и при необходимости приложите фото/скриншот, кликнув по ссылке: www.new.modi.ru/sd", "buttons": [{"text": "Проблемы с интернетом", "to": "s7"}, {"text": "Проблемы с оборудованием", "to": "s6"}, {"text": "Проблемы с 1С", "to": "s25"}, {"text": "Заявка в Service Desk", "to": "s33"}]}], "next": null}, "s27": {"title": "Нет", "blocks": [{"t": "msg", "text": "Были рады помочь. Хороших продаж!", "buttons": [{"text": "В начало", "to": "s26"}]}], "next": null}, "s28": {"title": "Сканер штрих кодов", "blocks": [{"t": "msg", "text": "Если у вас не работает сканер штрих кодов, либо работает некорректно, вытащите USB провод сканера из кассового моноблока и вставьте обратно. Проверьте работоспособность сканера. Если так же не заработал, подключите к другому USB порту на кассовом моноблоке.\n\nЕсли всё равно не работает, сделайте заявку на sd@modi.ru", "buttons": [{"text": "Назад", "to": "s6"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s29": {"title": "Замятие бумаги", "blocks": [{"t": "msg", "text": "Инструкция по устранению замятия на МФУ HP 137\nhttps://www.youtube.com/watch?v=YNrJ4CVN5OM\n\nИнструкция по устранению замятия на МФУ HP 426 и HP 428\nhttps://www.youtube.com/watch?v=e5NssR_zkLQ", "buttons": [{"text": "Назад", "to": "s19"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s30": {"title": "А как это сделать?", "blocks": [{"t": "delay", "seconds": 5}, {"t": "msg", "text": "Отключите провод питания от роутера на 10 секунд и подключите заново (прогружается он в течении 2-х минут).", "buttons": []}], "next": "s20"}, "s31": {"title": "Не включается", "blocks": [{"t": "msg", "text": "Проверьте питание. В розетку, в которую включен питающий шнур от компьютера, включите зарядку от телефона. Если телефон не заряжается, поменяйте розетку.\nОбратите внимание, если компьютер включен через ИБП (источник бесперебойного питания), работает ли он (на ИБП должны светиться индикаторы).\nВытащите вилку из розетки, подождите 10 секунд, подключите заново.\n\nПомогло?", "buttons": [{"text": "Помогло", "to": "s27"}, {"text": "Не помогло", "to": "s36"}]}], "next": null}, "s32": {"title": "Да, интернет не появ", "blocks": [{"t": "msg", "text": "Вставьте USB-модем в роутер Mikrotik.\nДалее перейдите по ссылке и сделайте заявку в техподдержку:\nwww.modi.ru/sd", "buttons": [{"text": "В начало", "to": "s26"}]}], "next": null}, "s33": {"title": "Заявка в Service Des", "blocks": [{"t": "notify"}], "next": "s26"}, "s34": {"title": "Компьютер директора", "blocks": [{"t": "msg", "text": "В чём проблема?", "buttons": [{"text": "Не включается", "to": "s31"}, {"text": "Тормозит", "to": "s36"}, {"text": "Издаёт посторонние звуки", "to": "s36"}, {"text": "Назад", "to": "s6"}]}], "next": null}, "s35": {"title": "Старт", "blocks": [{"t": "delay", "seconds": 5}, {"t": "input", "text": "Здравствуйте, {{first name}}!\nВведите номер и название магазина, причину обращения, а затем выберите пункт меню.\n\nОтзывы и предложения отправляйте на sd@modi.ru с темой \"Доработка телеграм бота\"", "save_to": "NameShop"}, {"t": "delay", "seconds": 3}], "next": "s26"}, "s36": {"title": "Тормозит", "blocks": [{"t": "msg", "text": "Перейдите по ссылке и заполните форму заявки www.modi.ru/sd", "buttons": [{"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s37": {"title": "Работа с новым ТСД А", "blocks": [{"t": "msg", "text": "ТСД АТОЛ", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}, "s38": {"title": "Ошибка 4128", "blocks": [{"t": "msg", "text": "Для исправления ошибки 4128 необходимо позвонить в службу поддержки эквайринга СБЕРа по номеру 88003500123 и сделать заявку.", "buttons": [{"text": "Назад", "to": "s11"}, {"text": "В начало", "to": "s26"}]}], "next": null}, "s39": {"title": "Индикации нет", "blocks": [{"t": "msg", "text": "Проверьте поступает ли питание на роутер, переключите роутер в другую розетку. \nЕсли роутер включен в ИБП (источник бесперебойного питания), проверьте включен ли он.\nПосле переключения розетки, если индикация появилась, подождите 2 минуты и проверьте интернет.", "buttons": [{"text": "Розетку поменяли", "to": "s13"}]}], "next": null}, "s40": {"title": "Возврат при оплате п", "blocks": [{"t": "msg", "text": "Возврат при оплате п", "buttons": [{"text": "Назад", "to": "s25"}, {"text": "В начало", "to": "s26"}, {"text": "Заявка в Service Desk", "to": "s18"}]}], "next": null}}};

// Кому слать уведомления «Заявка в Service Desk»: user_id в MAX через запятую в .env (ADMIN_USER_IDS). Пусто = не слать.
const ADMIN_USER_IDS = String($env.ADMIN_USER_IDS || '').split(',').map(s => s.trim()).filter(Boolean).map(Number);
const MAX_CHAIN = 25; // защита от зацикливания «Следующий шаг»

const upd = $input.first().json;
const store = $getWorkflowStaticData('global');
store.users = store.users || {};
const user = (store.users[upd.user_id] = store.users[upd.user_id] || { vars: {} });
if (upd.first_name) user.vars['first name'] = upd.first_name;

const actions = [];
const say = (text, buttons) => {
  const body = { text };
  if (buttons && buttons.length) {
    body.attachments = [{
      type: 'inline_keyboard',
      payload: { buttons: buttons.map(b => [{ type: 'callback', text: b.text, payload: 'go:' + b.to }]) },
    }];
  }
  actions.push({ kind: 'send', user_id: upd.user_id, body });
};
const fill = t => t.replace(/\{\{([^}]+)\}\}/g, (_, k) => user.vars[k.trim()] ?? '');

// Выполняет блоки шага начиная с индекса from; идёт по «Следующему шагу».
function run(stepId, from = 0, depth = 0) {
  const step = SCENARIO.steps[stepId];
  if (!step || depth > MAX_CHAIN) return;
  for (let i = from; i < step.blocks.length; i++) {
    const b = step.blocks[i];
    if (b.t === 'delay') {
      actions.push({ kind: 'delay', seconds: b.seconds });
    } else if (b.t === 'msg') {
      if (b.text.trim()) say(fill(b.text), b.buttons);
      else if (b.buttons.length) say('Выберите пункт', b.buttons);
    } else if (b.t === 'input') {
      say(fill(b.text));
      user.resume = { step: stepId, block: i + 1, save_to: b.save_to };
      return; // ждём ответ пользователя
    } else if (b.t === 'notify') {
      const info = `Заявка из бота: ${step.title}\nПользователь: ${upd.first_name || ''} (id ${upd.user_id})\n` +
        `Магазин/обращение: ${user.vars.NameShop || '—'}`;
      for (const id of ADMIN_USER_IDS) actions.push({ kind: 'send', user_id: id, body: { text: info } });
    }
  }
  if (step.next) run(step.next, 0, depth + 1);
}

const text = (upd.text || '').trim();
if (upd.type === 'callback') {
  if (upd.callback_id) actions.push({ kind: 'ack', callback_id: upd.callback_id });
  const target = String(upd.payload || '').replace(/^go:/, '');
  if (SCENARIO.steps[target]) { delete user.resume; run(target); }
} else {
  const low = text.toLowerCase();
  const kw = upd.type === 'start'
    ? { to: SCENARIO.start }
    : SCENARIO.keywords.find(k => low.includes(k.word.toLowerCase()));
  if (kw) {
    delete user.resume;
    run(kw.to);
  } else if (user.resume) {
    const r = user.resume;
    delete user.resume;
    user.vars[r.save_to] = text;
    run(r.step, r.block);
  } else {
    run(SCENARIO.start); // непонятный текст — начинаем сначала
  }
}

return actions.map(a => ({ json: a }));
